// ModelsKiroConn defines model for models.KiroConn.
type ModelsKiroConn struct {
	// AccessKeyId AccessKeyId for AWS
	AccessKeyId *string `json:"accessKeyId,omitempty"`

	// Bucket Bucket holding the user activity report CSVs
	Bucket *string `json:"bucket,omitempty"`

	// IdentityStoreId IdentityStoreId for AWS IAM Identity Center. Optional: it only resolves
	// display names. User identity is keyed on the User_Email column of the
	// report CSV, so collection works fully without it.
	IdentityStoreId *string `json:"identityStoreId,omitempty"`

	// IdentityStoreRegion IdentityStoreRegion may differ from the S3 region. Optional.
	IdentityStoreRegion *string `json:"identityStoreRegion,omitempty"`

	// PromptLogBucket PromptLogBucket holding the interaction logs. Kiro recommends a bucket
	// separate from the report one; when empty this falls back to Bucket so
	// that single-bucket and dual-bucket setups share one code path.
	PromptLogBucket *string `json:"promptLogBucket,omitempty"`

	// PromptLogPrefix PromptLogPrefix within PromptLogBucket; defaults to
	// DefaultPromptLogPrefix when empty
	PromptLogPrefix *string `json:"promptLogPrefix,omitempty"`

	// RateLimitPerHour RateLimitPerHour limits the requests sent to AWS
	RateLimitPerHour *int `json:"rateLimitPerHour,omitempty"`

	// Region Region of the buckets, and of the Kiro profile that writes to them
	Region *string `json:"region,omitempty"`

	// ReportPrefix ReportPrefix within Bucket; defaults to DefaultReportPrefix when empty
	ReportPrefix *string `json:"reportPrefix,omitempty"`

	// SecretAccessKey SecretAccessKey for AWS
	SecretAccessKey *string `json:"secretAccessKey,omitempty"`
}

